3:/**
4: * Versions are canonical MAJOR.MINOR.PATCH strings: three non-negative safe
5: * integers with no leading zeroes, suffixes, or whitespace. parse returns their
6: * numeric triple; compare accepts version strings and returns -1, 0, or 1.
7: *
8: * Ranges are strings containing one or more whitespace-separated AND terms:
9: * exact versions, *, ^version, ~version, >=version, >version, <=version, or
10: * <version. Surrounding whitespace is ignored; empty ranges are invalid.
11: * Caret is >= the base and < the next major, except that a zero major uses the
12: * next minor, or the next patch when both major and minor are zero. Tilde is
13: * >= the base and < the next minor. Invalid versions/ranges throw TypeError.
14: */
15:function parse(version) {
16:  if (typeof version !== 'string' || !/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/.test(version)) {
17:    throw new TypeError('Invalid version');
18:  }
19:  const parts = version.split('.').map(Number);
20:  if (!parts.every(Number.isSafeInteger)) throw new TypeError('Invalid version');
21:  return parts;
22:}
23:
24:function compareParts(left, right) {
25:  for (let i = 0; i < 3; i += 1) {
26:    if (left[i] !== right[i]) return left[i] < right[i] ? -1 : 1;
27:  }
28:  return 0;
29:}
30:
31:function compare(left, right) {
32:  return compareParts(parse(left), parse(right));
33:}
34:
35:// Internal compiled predicates also let the resolver validate every range once.
36:function compileRange(range) {
37:  if (typeof range !== 'string' || range.trim() === '') throw new TypeError('Invalid range');
38:  const terms = range.trim().split(/\s+/).map(term => {
39:    if (term === '*') return () => true;
40:    const match = /^(\^|~|>=|<=|>|<)?(.+)$/.exec(term);
41:    if (!match) throw new TypeError('Invalid range');
42:    const operator = match[1] || '';
43:    const base = parse(match[2]);
44:    if (operator === '^' || operator === '~') {
45:      const upper = operator === '~' ? [base[0], base[1] + 1, 0]
46:        : [base[0] + 1, 0, 0];
47:      return version => compareParts(version, base) >= 0 && compareParts(version, upper) < 0;
48:    }
49:    return version => {
50:      const order = compareParts(version, base);
51:      switch (operator) {
52:        case '': return order === 0;
53:        case '>=': return order >= 0;
54:        case '>': return order > 0;
55:        case '<=': return order <= 0;
56:        case '<': return order < 0;
57:        default: throw new TypeError('Invalid range');
58:      }
59:    };
60:  });
61:  return version => terms.every(term => term(version));
62:}
63:
64:function satisfies(version, range) {
65:  const parts = parse(version);
66:  return compileRange(range)(parts);
67:}
68:
69:module.exports = { parse, compare, satisfies, compileRange };

