        case '>=': return order >= 0;
        case '>': return order > 0;
        case '<=': return order <= 0;
        case '<': return order < 0;
        default: throw new TypeError('Invalid range');
      }
    };
  });
  return version => terms.every(term => term(version));
}

function satisfies(version, range) {
  const parts = parse(version);
  return compileRange(range)(parts);
}

