'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare, parse } = require('./src/semver');

// Caret/tilde.
assert.equal(satisfies('0.2.9', '^0.2.3'), true);
assert.equal(satisfies('0.3.0', '^0.2.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.0', '^1.2.0'), true);
assert.equal(satisfies('2.0.0', '^1.2.0'), false);
assert.equal(compare('1.10.0', '1.9.0'), 1);

// Backtracking with stale-constraint leak in old code.
const reg1 = {
  a: { '2.0.0': { b: '^2.0.0', c: '^1.0.0' }, '1.0.0': { c: '^1.0.0' } },
  b: { '2.0.0': { c: '^2.0.0' } },
  c: { '2.0.0': {}, '1.0.0': {} },
};
assert.deepEqual(resolve(reg1, { a: '*' }), { a: '1.0.0', c: '1.0.0' });

// Cycle + self-dependency.
assert.deepEqual(resolve({ a: { '1.0.0': { b: '*' } }, b: { '1.0.0': { a: '1.0.0' } } }, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
assert.deepEqual(resolve({ a: { '2.0.0': { a: '^1.0.0' }, '1.0.0': { a: '*' } } }, { a: '*' }), { a: '1.0.0' });
assert.equal(resolve({}, { x: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

// Long chain.
const N = 200000;
const chain = {};
for (let i = 0; i < N; i++) chain['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '*' } : { p0: '*' } };
const out = resolve(chain, { p0: '*' });
assert.equal(Object.keys(out).length, N);

// Naive recursive reference of the spec.
function reference(registry, root) {
  const cat = {};
  for (const n of Object.keys(registry)) cat[n] = Object.keys(registry[n]).sort((x, y) => compare(y, x));
  function go(selected, cons, queue, cursor) {
    while (cursor < queue.length && selected[queue[cursor]]) cursor++;
    if (cursor === queue.length) return selected;
    const name = queue[cursor];
    for (const v of cat[name] || []) {
      if (!cons.filter(c => c[0] === name).every(c => satisfies(v, c[1]))) continue;
      const sel = { ...selected, [name]: v };
      const deps = registry[name][v];
      const nc = cons.concat(Object.keys(deps).map(d => [d, deps[d]]));
      if (!nc.every(c => !sel[c[0]] || satisfies(sel[c[0]], c[1]))) continue;
      const r = go(sel, nc, queue.concat(Object.keys(deps)), cursor + 1);
      if (r) return r;
    }
    return null;
  }
  const cons = Object.keys(root).map(n => [n, root[n]]);
  return go({}, cons, Object.keys(root), 0);
}

let seed = 7;
const rnd = k => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) % k);
const ranges = ['*', '^1.0.0', '^0.2.0', '~1.1.0', '>=1.2.0', '<1.1.0', '2.0.0', '>0.2.0 <1.2.0', '^0.0.1'];
const versions = ['0.0.1', '0.0.2', '0.2.0', '0.2.5', '1.0.0', '1.1.0', '1.1.3', '1.2.0', '1.10.0', '2.0.0'];
let solved = 0;
for (let t = 0; t < 3000; t++) {
  const names = ['a', 'b', 'c', 'd', 'e', 'f'].slice(0, 2 + rnd(5));
  const registry = {};
  for (const n of names) {
    if (rnd(8) === 0) continue;
    registry[n] = {};
    const count = 1 + rnd(4);
    for (let i = 0; i < count; i++) {
      const deps = {};
      for (let j = rnd(3); j > 0; j--) deps[names[rnd(names.length)]] = ranges[rnd(ranges.length)];
      registry[n][versions[rnd(versions.length)]] = deps;
    }
  }
  const root = {};
  for (let j = 1 + rnd(2); j > 0; j--) root[names[rnd(names.length)]] = ranges[rnd(ranges.length)];
  const expected = reference(registry, root);
  if (expected) solved++;
  assert.deepEqual(resolve(registry, root), expected, JSON.stringify({ registry, root }));
}
console.log('ok', solved, 'solvable of 3000');

